import { ref, onMounted } from 'vue';
import axios from 'axios';
export default {
  __name: 'Containers',
  setup(__props, {
    expose: __expose
  }) {
    const containers = ref({});
    const fetchContainers = async () => {
      try {
        const res = await axios.get('http://localhost:8081/container/list');
        containers.value = res.data;
      } catch (err) {
        console.error('获取网络列表失败', err);
      }
    };

    // 暴露方法供外部调用
    __expose({
      fetchContainers,
      containers
    });
    onMounted(() => {
      fetchContainers();
    });
    const __returned__ = {
      containers,
      fetchContainers,
      ref,
      onMounted,
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
